import{_ as t,o as d,c as o,a2 as a}from"./chunks/framework.BXzK3EA4.js";const h=JSON.parse('{"title":"47 - SMTP Configuration","description":"","frontmatter":{},"headers":[],"relativePath":"developers/design-documentation/47-smtp-configuration.md","filePath":"developers/design-documentation/47-smtp-configuration.md"}'),r={name:"developers/design-documentation/47-smtp-configuration.md"};function s(i,e,n,c,l,p){return d(),o("div",null,[...e[0]||(e[0]=[a('<h1 id="_47-smtp-configuration" tabindex="-1">47 - SMTP Configuration <a class="header-anchor" href="#_47-smtp-configuration" aria-label="Permalink to &quot;47 - SMTP Configuration&quot;">​</a></h1><h2 id="storage" tabindex="-1">Storage <a class="header-anchor" href="#storage" aria-label="Permalink to &quot;Storage&quot;">​</a></h2><p>SMTP settings are columns on the single <code>Settings</code> row (<code>__tablename__ = &quot;settings&quot;</code>) in <code>database/settings_db.py</code>; there is no separate SMTP database or email service module.</p><table tabindex="0"><thead><tr><th>Column</th><th>Type</th><th>Notes</th></tr></thead><tbody><tr><td><code>smtp_server</code></td><td>String(255)</td><td>Hostname</td></tr><tr><td><code>smtp_port</code></td><td>Integer</td><td>Route default is 587 when the form omits it</td></tr><tr><td><code>smtp_username</code></td><td>String(255)</td><td></td></tr><tr><td><code>smtp_password_encrypted</code></td><td>Text</td><td>Fernet ciphertext, never plaintext</td></tr><tr><td><code>smtp_use_tls</code></td><td>Boolean</td><td>Defaults to <code>True</code></td></tr><tr><td><code>smtp_from_email</code></td><td>String(255)</td><td></td></tr><tr><td><code>smtp_helo_hostname</code></td><td>String(255)</td><td>Optional EHLO/HELO override</td></tr></tbody></table><p>New password writes use <code>_get_smtp_fernet()</code>: PBKDF2-HMAC-SHA256, 100,000 iterations, keyed on the validated <code>API_KEY_PEPPER</code> with the salt from <code>SMTP_KEY_SALT</code> (env var, default <code>smtp-tradeboard-salt</code>). <code>_decrypt_password()</code> falls back to <code>_legacy_smtp_fernet()</code> (the raw pepper padded to 32 bytes, no KDF) for values written before that upgrade, and re-saving the settings migrates them forward. Decrypted passwords must never be returned by profile/admin APIs or logged.</p><h2 id="authenticated-routes" tabindex="-1">Authenticated Routes <a class="header-anchor" href="#authenticated-routes" aria-label="Permalink to &quot;Authenticated Routes&quot;">​</a></h2><p><code>blueprints/auth.py</code> exposes:</p><table tabindex="0"><thead><tr><th>Method/path</th><th>Purpose</th></tr></thead><tbody><tr><td><code>POST /auth/smtp-config</code></td><td>Update settings from form fields; a blank password preserves the existing secret</td></tr><tr><td><code>POST /auth/test-smtp</code></td><td>Validate recipient and send a test message</td></tr><tr><td><code>POST /auth/debug-smtp</code></td><td>Run connection/auth diagnostics</td></tr><tr><td><code>GET /auth/profile-data</code></td><td>Return non-secret config and password-present state</td></tr></tbody></table><p>The React configuration UI is the SMTP tab in <code>frontend/src/pages/Profile.tsx</code>.</p><h2 id="delivery" tabindex="-1">Delivery <a class="header-anchor" href="#delivery" aria-label="Permalink to &quot;Delivery&quot;">​</a></h2><p><code>utils/email_utils.py</code> exposes <code>send_test_email()</code>, <code>send_password_reset_email()</code>, <code>send_email()</code>, and <code>validate_smtp_settings()</code>. Port 465 uses <code>smtplib.SMTP_SSL</code> from the start; any other port opens a plain <code>SMTP</code> connection and upgrades with <code>starttls()</code> when <code>smtp_use_tls</code> is set. <code>smtp_helo_hostname</code> is passed to <code>ehlo()</code>, falling back to <code>smtp_server</code> when it is blank. <code>utils/email_debug.py</code> performs staged diagnostics behind <code>POST /auth/debug-smtp</code>.</p><h2 id="security-rules" tabindex="-1">Security Rules <a class="header-anchor" href="#security-rules" aria-label="Permalink to &quot;Security Rules&quot;">​</a></h2><ul><li>Require a valid app session and CSRF token for changes.</li><li>Preserve the existing password when the form leaves it blank.</li><li>Return password presence only, never ciphertext or plaintext.</li><li>Do not include credentials in SMTP errors or logs.</li><li>Prefer provider app passwords and TLS/SSL.</li><li>Treat debug output as authenticated operational data.</li></ul><h2 id="key-files" tabindex="-1">Key Files <a class="header-anchor" href="#key-files" aria-label="Permalink to &quot;Key Files&quot;">​</a></h2><table tabindex="0"><thead><tr><th>File</th><th>Purpose</th></tr></thead><tbody><tr><td><code>database/settings_db.py</code></td><td>Settings and SMTP encryption</td></tr><tr><td><code>utils/email_utils.py</code></td><td>Test/reset/general delivery</td></tr><tr><td><code>utils/email_debug.py</code></td><td>Connection diagnostics</td></tr><tr><td><code>blueprints/auth.py</code></td><td>Configuration routes</td></tr><tr><td><code>frontend/src/pages/Profile.tsx</code></td><td>SMTP form</td></tr></tbody></table>',15)])])}const m=t(r,[["render",s]]);export{h as __pageData,m as default};
